/* Deep Roots — images
   Every image used by the app lives here, embedded as a data URI (WebP, 1400px wide),
   so index.html stays clean and the app still works by double-click with no extra files.
   Fields:  src  the image (data URI)   alt  short description for screen readers
            pos  optional CSS object-position, i.e. which part of the image stays visible when cropped
   Where each one appears is set in index.html (BANNER map).
     hero     landing page banner              (image prompt 1: path through a wheat field)
     passage  top of the Passage card          (image prompt 2: open book with rays of light)
     nuggets  top of the Nuggets card          (image prompt 3: olive branch on parchment)
     prayer   top of the Prayer card           (image prompt 4: clay lamp on a windowsill)
   To swap an image: replace its src with a new data URI (or a relative path such as "images/hero.webp"). */

const IMAGES={
 hero:{
  pos:"50% 60%",
  alt:"A watercolor path winding through a golden wheat field toward distant hills at sunrise",
  src:"data:image/webp;base64,"
 },
 passage:{
  pos:"50% 72%",
  alt:"An open book on a rock with rays of light rising from its pages over quiet hills",
  src:"data:image/webp;base64,"
 },
 nuggets:{
  pos:"30% 45%",
  alt:"An olive branch resting on aged parchment paper",
  src:"data:image/webp;base64,"
 },
 prayer:{
  pos:"30% 68%",
  alt:"A small clay lamp glowing on a windowsill at dusk, looking out over hills and a town",
  src:"data:image/webp;base64,"
 },
};
